function out=sat_d027_measure(sig,spec,scenarioId)
%SAT_D027_MEASURE Cold-start current-regulation evidence.
out=struct('schema',"simuverity.d027-direct-measurement.v1",'scenario',string(scenarioId),'valid',false,'detail',"UNINITIALIZED",'cold_start',struct());if ~isstruct(spec)||~isfield(spec,'id')||string(spec.id)~="D027",out.detail="NOT_D027";return;end,if ~isstruct(sig)||~isfield(sig,'Iabc'),out.detail="IABC_MISSING";return;end,amp=amp_for(string(scenarioId));out.cold_start=component(sig.Iabc,50,amp/sqrt(2));out.valid=out.cold_start.valid;out.detail=tern(out.valid,"OK","COLD_START_INVALID");
end
function o=component(s,f,target),o=struct('schema',"simuverity.d027-cold-start.v1",'valid',false,'scope',"closed_loop_current_establishment",'score_role',"score-bearing",'cycle_time',zeros(0,1),'cycle_rms',zeros(0,3),'target_rms_a',target,'worst_relative_error',zeros(0,1),'settling_time_s',NaN,'settling_time_fraction',NaN,'normalized_iae',NaN,'settling_q',0,'iae_q',0,'q',0);if ~validsig(s),return;end,t=double(s.t(:));Y=double(s.Y(:,1:3));T=1/f;n=floor((t(end)-t(1))/T+1e-9);if n<4,return;end,e=t(1)+(0:n)*T;z=nan(n,3);for k=1:n,ix=t>e(k)&t<e(k+1);tt=[e(k);t(ix);e(k+1)];yy=[interp1(t,Y,e(k),'linear','extrap');Y(ix,:);interp1(t,Y,e(k+1),'linear','extrap')];z(k,:)=sqrt(trapz(tt,yy.^2,1)/T);end,err=max(abs(z-target)/target,[],2);u=utility(err,e);o.valid=true;o.cycle_time=e(2:end).';o.cycle_rms=z;o.worst_relative_error=err;o.settling_time_s=u.ts;o.settling_time_fraction=u.tf;o.normalized_iae=u.iae;o.settling_q=u.settling_q;o.iae_q=u.iae_q;o.q=u.q;end
function a=amp_for(id),if id=="reference_up",a=6;elseif id=="reference_down",a=4;else,a=5;end,end
% Full credit requires establishment within one 50 Hz cycle and <=1% normalized IAE.
function q=utility(err,e),k=find(arrayfun(@(j)all(err(j:end)<=.10),1:numel(err)),1);dur=e(end)-e(1);if isempty(k),ts=dur;else,ts=e(k+1)-e(1);end,tf=min(max(ts/max(dur,eps),0),1);iae=mean(min(err,2));qt=anchor(tf,[0 1/15 2/15 3/15 1],[1 1 .30 .10 0]);qe=anchor(iae,[0 .01 .01815 .03 .05],[1 1 .35 .10 0]);qq=sqrt(mean([qt qe])*min([qt qe]));q=struct('ts',ts,'tf',tf,'iae',iae,'settling_q',qt,'iae_q',qe,'q',qq);end
function q=anchor(v,x,y),v=min(max(double(v),x(1)),x(end));q=interp1(x,y,v,'linear');end
function ok=validsig(s),ok=isstruct(s)&&isfield(s,'t')&&isfield(s,'Y')&&numel(s.t)>=16&&size(s.Y,1)==numel(s.t)&&size(s.Y,2)>=3&&all(isfinite(s.t))&&all(isfinite(s.Y(:,1:3)),'all')&&all(diff(double(s.t(:)))>0);end
function x=tern(c,a,b),if c,x=a;else,x=b;end,end
